import json
d=json.load(open('.agents/skills/adhd-md/references/rule-definitions.json'))
rules={r['id']:r for r in d['rules']}
def scope_ok(r, scope):
    ax=r.get('axis','')
    return scope in ax.split('/')
sel=[]
for rid,r in rules.items():
    if r.get('min_level',1)>3: continue
    if not (scope_ok(r,'F')): continue
    sel.append((rid, r.get('group'), r.get('name'), r.get('axis'), r.get('min_level'), r.get('automation'), r.get('status')))
print(len(sel))
for s in sorted(sel, key=lambda x:(x[0][0], x[0])):
    print(s)
